ualPrice - $amount); ?> )                   <br/> <br/><span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo $batchOfferPrice - $gstAmount; ?>                                      <?php if($gstAmount != 0){ ?>                     <br/> <br/> <span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo $gstAmount; ?>                     <?php }else{ ?>                     <br/> <br/> <span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo $IGST; ?>                     <br/> <br/> <span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo $CGST; ?>                                          <?php } ?>                                                           </td>                    				</tr>				             <?php } else{ ?>                                <tr class="item">					<td>Discount                      <br/> <br/> Sub Total                     </td>					<td>-( <span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo ($actualPrice - $amount); ?> )                   <br/> <br/> <span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span> <?php echo $amount; ?>                    </td>                    				</tr>				             <?php  } ?>				                				<tr class="">				<td> <span style=" font-weight: bold;">Total</span></td>					<td><span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span><?php echo $batchOfferPrice; ?></td>				</tr>				<tr class="heading">					<td>Amount Received</td>					<td><span style="font-family: DejaVu Sans; sans-serif;">&#8377;</span><?php echo $amount; ?></td>				</tr>                <tr class="item">					<td>AmountReceived in Words : </td>					<td><?php echo $amountInWords; ?>                    </td>				           		</table>                   <div class="notes">                    <p style="font-weight: 700;">Notes:</p>                    <p style="padding